};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform FireParams {
  vec4 fireColorInner;
  vec4 fireColorOuter;
  vec4 params;
};
float hash2(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash2(i), hash2(i + vec2(1.0, 0.0)), f.x),
    mix(hash2(i + vec2(0.0, 1.0)), hash2(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  float f = 1.0;
  for (int i = 0; i < 3; i++) {
    v += a * noise(p * f);
    f *= 2.0;
    a *= 0.5;
  }
  return v;
}
vec4 frag () {
  vec4 o = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  float t = cc_time.x * params.y;
  float n1 = fbm(uv0 * params.z * 0.6 + vec2(0.0, t * 0.3));
  float n2 = fbm(uv0 * params.z * 1.4 + vec2(t * 0.5, t * 0.8));
  float n3 = noise(uv0 * params.z * 3.0 + vec2(t * 1.2, -t * 1.0)) * 0.3;
  float flame = n1 * 0.5 + n2 * 0.35 + n3 * 0.15;
  float flameSmooth = smoothstep(0.2, 0.7, flame);
  vec3 fireColor = mix(fireColorOuter.rgb, fireColorInner.rgb, flameSmooth);
  float peak = smoothstep(0.8, 0.95, flame);
  fireColor = mix(fireColor, vec3(1.0, 1.0, 0.95), peak * 0.4);
  vec2 uvDistorted = uv0;
  if (params.w > 0.01) {
    float dx = (n2 - 0.5) * params.w * 0.03;
    float dy = (n1 - 0.5) * params.w * 0.03;
    uvDistorted = uv0 + vec2(dx, dy);
  }
  float fireMask = smoothstep(0.25, 0.65, flame) * params.x;
  vec4 texDistorted = CCSampleWithAlphaSeparated(cc_spriteTexture, uvDistorted);
  o.rgb = mix(texDistorted.rgb, fireColor, fireMask * texDistorted.a);
  ALPHA_TEST(o);
  o *= color;
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

